          el.title = 'Could not determine site freshness.';
          return;
        }
        const now = new Date();
        const diffMs = now - lastUpdate;
        const diffHours = diffMs / (1000 * 60 * 60);

        if (diffHours < 2) {
          el.textContent = 'Current';
          el.style.color = '#79c0ff';
          el.title = 'Site data is current.';
        } else if (diffHours < 24) {
